import { execSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

let id = 'unknown';
let when = '';
try {
  id = execSync('git rev-parse --short HEAD').toString().trim();
  when = execSync('git log -1 --format=%cI').toString().trim();
} catch {
  // non-git build; leave placeholder
}

const out = `/**
 * AUTO-GENERATED by scripts/write-build-id.mjs at build time.
 * Rendered in the footer so "is it deployed?" is answerable on sight.
 */
export const BUILD_ID = '${id}';
export const BUILD_TIME = '${when}';
`;
writeFileSync(new URL('../src/lib/build-id.ts', import.meta.url), out);
console.log(`build-id: ${id} ${when}`);
